import hashlib
import math

class BloomFilter:
    """
    A simple implementation of a Bloom Filter. This data structure allows for
    efficient probabilistic membership testing, meaning it can quickly test
    whether an item is in a set, with a possibility of false positives.

    The optimal size of the bit array and the number of hash functions are computed
    based on the expected number of items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate optimal size of bit array (m) and number of hash functions (k)
        self.size = self._calculate_size(expected_items, false_positive_rate)
        self.hash_count = self._calculate_hash_count(self.size, expected_items)

        # Initialize the bit array
        self.bit_array = [0] * self.size

    def _calculate_size(self, n: int, p: float) -> int:
        """Calculates the optimal size of the bit array based on n and p."""
        return max(1, int(-n * math.log(p) / (math.log(2) ** 2)))

    def _calculate_hash_count(self, m: int, n: int) -> int:
        """Calculates the optimal number of hash functions."""
        if m == 0:
            return 0
        return max(1, int((m / n) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generates multiple hash values for the given item."""
        hash_values = []
        for i in range(self.hash_count):
            hash_value = int(hashlib.md5((item + str(i)).encode()).hexdigest(), 16) % self.size
            hash_values.append(hash_value)
        return hash_values

    def add(self, item: str) -> None:
        """Adds an item to the Bloom Filter."""
        for hash_value in self._hashes(item):
            self.bit_array[hash_value] = 1

    def contains(self, item: str) -> bool:
        """Checks if an item is possibly in the Bloom Filter."""
        return all(self.bit_array[hash_value] for hash_value in self._hashes(item))

